K("G6_TB_45_1564.3", r"$0{,}055$ и $-0{,}55$", "−(4,7m + 2,8m − 5,7m) − 3,7m = −5,5m: 0,055 при m = −0,01 и −0,55 при m = 0,1 (было 0,057 и −0,57)")
